import{_ as t,o as a,c as o,ah as r}from"./chunks/framework.C-FRNfAJ.js";const m=JSON.parse('{"title":"Suivre sa formation","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/apprenant/formation.md","filePath":"src/guide/apprenant/formation.md"}'),n={name:"guide/apprenant/formation.md"};function s(i,e,l,u,c,d){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="suivre-sa-formation" tabindex="-1">Suivre sa formation <a class="header-anchor" href="#suivre-sa-formation" aria-label="Permalink to &quot;Suivre sa formation&quot;">​</a></h1><p>Une fois votre première tranche payée, vous passez de l&#39;administratif à la formation elle-même, qui se déroule dans <strong>Sève</strong>. Kura continue de suivre votre présence et vos résultats.</p><h2 id="l-ouverture-de-votre-acces-a-seve" tabindex="-1">L&#39;ouverture de votre accès à Sève <a class="header-anchor" href="#l-ouverture-de-votre-acces-a-seve" aria-label="Permalink to &quot;L&#39;ouverture de votre accès à Sève&quot;">​</a></h2><p>Votre compte Sève s&#39;ouvre <strong>automatiquement au paiement de la première tranche</strong>. Si une entreprise finance une part de votre formation, il faut que <strong>les deux parts</strong> de cette première tranche soient réglées.</p><p>Vous êtes inscrit au cours de votre cohorte et vous recevez votre <strong>livret d&#39;accueil</strong> (<code>LA-NB-AAAA-XXX</code>) : par e-mail, puis dans <strong>Mon inscription</strong> et <strong>Mes documents</strong>. Il présente votre formation et, nommément, l&#39;équipe de la cohorte avec ses adresses e-mail. Un changement de cohorte en produit un nouveau ; l&#39;ancien est conservé.</p><p>Pour vous connecter à Sève, utilisez votre <strong>compte NextBoxx</strong> : Sève s&#39;appuie sur Kura pour vous identifier, il n&#39;y a pas de second mot de passe à retenir.</p><h2 id="la-presence" tabindex="-1">La présence <a class="header-anchor" href="#la-presence" aria-label="Permalink to &quot;La présence&quot;">​</a></h2><ul><li><strong>Classes virtuelles.</strong> Votre présence est relevée dans Sève et remonte automatiquement dans Kura, chaque heure. Elle ne se modifie pas dans Kura ; en cas d&#39;écart, le journal de la classe virtuelle fait foi.</li><li><strong>Classes en présentiel.</strong> Le Formateur Principal de la cohorte saisit la présence de chaque apprenant en présentiel ou en hybride après la séance. Il peut la corriger ensuite.</li></ul><p>Un <strong>retard compte comme une présence</strong> ; une <strong>absence excusée compte comme une absence</strong>.</p><p>Votre taux d&#39;absence est le temps des séances manquées rapporté au volume horaire de la formation (500 h, 700 h pour Développement Web &amp; Mobile, ou 250 h). Quand il dépasse <strong>30 %</strong>, vous êtes prévenu, ainsi que l&#39;équipe pédagogique, une seule fois.</p><h2 id="les-notes-et-les-blocs" tabindex="-1">Les notes et les blocs <a class="header-anchor" href="#les-notes-et-les-blocs" aria-label="Permalink to &quot;Les notes et les blocs&quot;">​</a></h2><p>La formation se découpe en <strong>blocs de compétences</strong>, chacun noté sur 20 dans Sève. Les notes remontent dans Kura chaque heure.</p><table tabindex="0"><thead><tr><th>Note d&#39;un bloc</th><th>Effet</th></tr></thead><tbody><tr><td>10/20 ou plus</td><td>Bloc validé</td></tr><tr><td>De 8 à moins de 10</td><td>Bloc non validé, mais compensable par la moyenne</td></tr><tr><td>Moins de 8</td><td>Éliminatoire</td></tr></tbody></table><p>Votre <strong>moyenne</strong> est pondérée par la durée de chaque bloc, en semaines. Elle est recalculée à chaque lecture. Si un bloc a été tenté plusieurs fois, la note retenue est celle de la dernière tentative notée.</p><h3 id="le-rattrapage" tabindex="-1">Le rattrapage <a class="header-anchor" href="#le-rattrapage" aria-label="Permalink to &quot;Le rattrapage&quot;">​</a></h3><p>Pour un bloc sous 10/20, un Formateur Principal de votre cohorte ou le Coordinateur peut ouvrir un <strong>rattrapage</strong> :</p><ul><li>au plus <strong>2 rattrapages</strong> par bloc (3 tentatives en tout) ;</li><li><strong>15 jours au moins</strong> après votre dernière note sur ce bloc ;</li><li>il se remplit avec la première note donnée dans Sève après son ouverture, et peut être annulé tant qu&#39;il n&#39;est pas noté.</li></ul><h2 id="le-projet-tutore-la-soutenance-et-le-stage" tabindex="-1">Le projet tutoré, la soutenance et le stage <a class="header-anchor" href="#le-projet-tutore-la-soutenance-et-le-stage" aria-label="Permalink to &quot;Le projet tutoré, la soutenance et le stage&quot;">​</a></h2><p>En plus des blocs, le Coordinateur saisit les décisions du <strong>jury</strong> :</p><ul><li>le <strong>projet tutoré</strong> : son sujet, s&#39;il est validé, sa note ;</li><li>la <strong>soutenance</strong> : sa date, si elle est validée, sa note ;</li><li>le <strong>stage</strong> : l&#39;entreprise, et si le stage est validé.</li></ul><p>Les notes du jury restent <strong>hors de la moyenne</strong>. La soutenance validée est une condition du certificat ; le stage, lui, ne bloque pas le certificat. Lorsque le jury a statué sur toutes les soutenances, un <strong>procès-verbal</strong> (<code>PVS-NB-AAAA-XXX</code>) est produit, numéroté et scellé.</p><h2 id="la-convention-de-stage" tabindex="-1">La convention de stage <a class="header-anchor" href="#la-convention-de-stage" aria-label="Permalink to &quot;La convention de stage&quot;">​</a></h2><p>Si votre formation comporte un stage, le Coordinateur saisit les informations dans Kura : l&#39;entreprise d&#39;accueil et son contact signataire, le Coach-Tuteur de votre cohorte qui encadre le stage, les dates et la mission. Il envoie ensuite la <strong>convention de stage</strong> en signature. Tant que personne n&#39;a signé, il peut la modifier ; une modification annule l&#39;envoi.</p><ul><li><strong>Vous</strong>, apprenant majeur, la signez dans votre compte avec un code reçu par e-mail. Un mineur passe par son représentant légal, avec un lien valable 7 jours.</li><li><strong>L&#39;entreprise</strong> signe par un lien valable 7 jours et un code, sans avoir de compte.</li><li>edPage group contre-signe ensuite. Le PDF scellé (<code>CONVS-NB-AAAA-XXX</code>) est envoyé à vous, au Coach-Tuteur, à l&#39;entreprise et à votre représentant légal s&#39;il y en a un.</li></ul><p>Le stage fait partie de la formation et ne donne lieu à aucun contrat de travail.</p><h2 id="vos-documents-de-suivi" tabindex="-1">Vos documents de suivi <a class="header-anchor" href="#vos-documents-de-suivi" aria-label="Permalink to &quot;Vos documents de suivi&quot;">​</a></h2><p>Tout ce qui est produit pour vous (livret, factures, conventions, relevé de notes) est dans <strong>Mes documents</strong>.</p>',27)])])}const v=t(n,[["render",s]]);export{m as __pageData,v as default};
